import XCTest

final class UnfollowTests: XCTestCase {
    func testUnfollow() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 5) {
            openButton.tap()
        }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()

        let whiskers = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'whiskers'")).firstMatch
        _ = whiskers.waitForExistence(timeout: 20)

        let following = app.buttons.matching(NSPredicate(format: "label == 'Following'")).firstMatch
        let found = following.waitForExistence(timeout: 20)
        print("DUMP_BEGIN")
        print(app.debugDescription)
        print("DUMP_END")
        XCTAssertTrue(found, "Following button not found")
        following.tap()
        sleep(2)
        print("POST_TAP_BEGIN")
        print(app.debugDescription)
        print("POST_TAP_END")
    }
}

