import XCTest

final class ChatUITests: XCTestCase {
    func testOpenChat() throws {
        let sb = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        var usedDeepLink = false
        let openBtn = sb.buttons["Open"]
        if openBtn.waitForExistence(timeout: 5) {
            openBtn.tap()
            usedDeepLink = true
            sleep(3)
        } else {
            app.launch()
            sleep(2)
        }

        var tapped = false
        for _ in 0..<15 {
            let candidates = app.buttons.matching(
                NSPredicate(format: "label CONTAINS[cd] 'chat' OR label CONTAINS[cd] 'message'")
            )
            let n = candidates.count
            for i in 0..<n {
                let el = candidates.element(boundBy: i)
                if el.frame.minY > 600 && el.isHittable {
                    el.tap()
                    tapped = true
                    break
                }
            }
            if tapped { break }
            if usedDeepLink { break }
            sleep(1)
        }

        sleep(2)
        try? app.debugDescription.write(toFile: "/tmp/chattest-debug.txt", atomically: true, encoding: .utf8)
        XCTAssertTrue(tapped || usedDeepLink, "could not open chat")
        sleep(2)
    }
}

