import XCTest

final class BlueskyUITests: XCTestCase {
    func testBluesky() throws {
        let sb = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let openBtn = sb.buttons["Open"]
        if openBtn.waitForExistence(timeout: 5) {
            openBtn.tap()
            sleep(3)
        }
        app.activate()
        sleep(2)

        let postsTab = app.descendants(matching: .any).matching(NSPredicate(format: "label == %@", "Posts")).firstMatch
        if !postsTab.waitForExistence(timeout: 10) {
            let name = app.staticTexts.matching(NSPredicate(format: "label CONTAINS %@", "whiskers")).firstMatch
            if name.waitForExistence(timeout: 10) {
                let f = name.frame
                let target = CGPoint(x: f.minX + 60, y: f.minY + 10)
                let coord = XCUICoordinate(element: app, normalizedOffset: CGVector(dx: target.x / app.frame.width, dy: target.y / app.frame.height))
                coord.tap()
                sleep(3)
            }
            _ = postsTab.waitForExistence(timeout: 10)
        }

        try? app.debugDescription.write(toFile: "/tmp/bsky-pre.txt", atomically: true, encoding: .utf8)

        let following = app.buttons.matching(NSPredicate(format: "label == %@", "Following")).firstMatch
        let found = following.waitForExistence(timeout: 10)
        if found {
            following.tap()
        }
        sleep(3)
        try? app.debugDescription.write(toFile: "/tmp/bsky-post.txt", atomically: true, encoding: .utf8)
        XCTAssertTrue(found, "Following button not found")
    }
}

